mapper.select:
SELECT fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, fp.FINPROD_NAME finprodName, fp.TRADE_MARKET tradeMarket, sdl3.item_value tradeMarketStr, fpa.ISSUERSHORT issueRshortStr, fpa.NOM_CAPI issueAmt, fpa.PROTECT_OBJECT protectObject, sdl4.item_value protectObjectStr, fpa.REF_SEC_FEATURES refSecFeatures, fpa.REF_SEC refSec, fpa.REF_ENTITY refEntity, fp.MDATE mDate, fp.VDATE vDate, fpa.GRACE_PERIOD gracePeriod, fpa.BOOK_BUILDING_DATE pledgeDeadlineDate, fpa.PAY_DATE payDate, fpa.LISTING_DATE listingDate, fp.CALENDAR_ID calendarId, fp.ISSUE_PRICE issuePrice, fccr.BASIS ratebasic, fpa.SETTLE_METHOD settleMethod, sdl2.item_value settleMethodStr, fpa.IS_ALLOW_OVERWRITE isAllowOverwrite, sdl1.item_value isOrNoStr FROM FIN_PRODUCT fp LEFT JOIN FIN_PRODUCT_ADD fpa ON fp.FINPROD_ID = fpa.FINPROD_ID LEFT JOIN FIN_CASH_INFO fci ON fci.FINPROD_ID = fp.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE fccr ON fccr.FINPROD_ID = fp.FINPROD_ID AND fccr.CASH_ID = fci.CASH_ID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='YES_OR_NO' and sdl1.item_code = fpa.IS_ALLOW_OVERWRITE LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='SETTLE_METHOD' and sdl2.item_code = fpa.SETTLE_METHOD LEFT JOIN SYS_DATADICT_LIST sdl3 on sdl3.dict_code ='TRADE_PLACE' and sdl3.item_code = fp.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='PROTECT_OBJECT' and sdl4.item_code = fpa.PROTECT_OBJECT
AND fp.FINPROD_TYPE2 = #{finprodType2}
AND (fp.FINPROD_MARKET_ID IN
#{item}
)
AND fpa.REF_ENTITY = #{refEntity}
AND (fpa.REF_SEC IN
#{item}
)
AND fpa.ISSUERSHORT = #{issueRshortStr}
AND fp.vdate >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND fp.vdate <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND fp.mdate >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND fp.mdate <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
ORDER BY fp.FINPROD_ID

select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


        PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

select sum(qty) from (
select count(1) as qty from ETR_ENTRUST where FINPROD_ID=#{finprodId}

    and ENTRUST_STATUS not in ('05','07') 

union all
select count(1) as qty from WFL_ETR_ENTRUST where FINPROD_ID=#{finprodId}
union all
select count(1) as qty from TRD_FIN_PRODUCT_DEAL_TOTAL t where t.FINPROD_ID=#{finprodId}

    and t.IS_CANCEL ='N' 


    and t.ps not in ('T41')

union all
select count(1) as qty from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL where FINPROD_ID=#{finprodId}
)

SELECT
OUTPUT_VALUE_1 outputValue1,
OUTPUT_VALUE_2 outputValue2
FROM FIN_PRODUCT_TYPE_CONFIG
WHERE CONFIG_TYPE = #{configType}

    AND INPUT_VALUE_1 = #{inputValue1}


    AND INPUT_VALUE_2 = #{inputValue2}


    AND INPUT_VALUE_3 = #{inputValue3}
 and ROWNUM=1
